{
  "name": "@opencode-compat/facade-sdk",
  "version": "0.4.4",
  "description": "Install-override stand-in for @opencode-ai/sdk (classic + v2/client catalog bridge)",
  "type": "module",
  "license": "MPL-2.0",
  "author": "oakimov",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/oakimov/opencode-plugin-compat.git",
    "directory": "packages/facade-sdk"
  },
  "publishConfig": {
    "access": "public"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./v2": {
      "types": "./dist/v2/index.d.ts",
      "import": "./dist/v2/index.js"
    },
    "./v2/client": {
      "types": "./dist/v2/client.d.ts",
      "import": "./dist/v2/client.js"
    },
    "./v2/types": {
      "types": "./dist/v2/types.d.ts",
      "import": "./dist/v2/types.js"
    },
    "./v2/gen/client": {
      "types": "./dist/v2/gen/client.d.ts",
      "import": "./dist/v2/gen/client.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "README.md",
    "!dist/**/*.map"
  ],
  "scripts": {
    "build": "bunx tsc -p tsconfig.json",
    "typecheck": "bunx tsc -p tsconfig.json --noEmit",
    "prepack": "bunx tsc -p tsconfig.json"
  },
  "dependencies": {
    "@opencode-compat/adapter": "0.4.4",
    "@opencode-compat/profile": "0.4.4"
  },
  "devDependencies": {
    "typescript": "^5.8.3"
  },
  "bugs": {
    "url": "https://github.com/oakimov/opencode-plugin-compat/issues"
  },
  "homepage": "https://github.com/oakimov/opencode-plugin-compat/tree/main/packages/facade-sdk#readme",
  "keywords": [
    "opencode",
    "ocp",
    "facade",
    "sdk"
  ],
  "engines": {
    "bun": ">=1.2.0"
  }
}
